export default function Hero() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [hovered, setHovered] = useState(false);

  const handleHover = () => {
    if (!hovered) {
      setCurrentSlide((prev) => prev + 1);
      if (currentSlide >= 2) setCurrentSlide(0);
    }
  };

  const handleOut = () => {
    if (!hovered) {
      setCurrentSlide((prev) => prev - 1);
      if (currentSlide <= 0) setCurrentSlide(2);
    }
  };

  return (
    <div className="relative w-full min-h-[800px] bg-amber-900 text-stone-600 font-sans overflow-hidden">
      {/* Background Gradients */}
      <div className={`absolute top-0 left-0 w-full h-full pointer-events-none bg-gradient-to-br ${INITIAL_SLIDES[currentSlide].background} group-hover:animate-fade duration-1000 ease-in-out`}></div>

      {/* Inner Container */}
      <div className="relative z-10 max-w-6xl mx-auto px-6 flex flex-col items-center justify-center text-center sm:px-12 py-24 sm:py-40">

        {/* Decorative Glows */}
        <div className="absolute -top-24 left-1/2 -translate-x-1/2 w-[400px] h-[400px] bg-[#f3ece2] rounded-full blur-3xl pointer-events-none" />

        {/* Title and Subtitle */}
        <div className="mb-8">
          <h1 className="text-4xl sm:text-5xl lg:text-6xl font-extrabold tracking-tight text-stone-600 group-hover:text-amber-400 transition-colors duration-300">
            {INITIAL_SLIDES[currentSlide].title}
          </h1>
          <p className="text-stone-600 mt-4 text-base sm:text-lg max-w-xl mx-auto">
            {INITIAL_SLIDES[currentSlide].description}
          </p>
        </div>

        {/* Call-to-Action Buttons */}
        <div className="mt-12 sm:mt-16 space-x-4">
          <button 
            className="inline-flex items-center justify-center px-6 py-3 text-sm font-semibold rounded-xl bg-amber-800 hover:bg-amber-900 text-stone-600 border border-amber-900/40 shadow-lg transition-all duration-200 hover:shadow-2xl active:scale-95 group"
            onClick={() => setCurrentSlide((prev) => prev + 1)}
            onMouseEnter={handleHover}
            onMouseLeave={handleOut}
          >
            <Sparkles className="w-4 h-4 mr-2 text-amber-400 group-hover:text-amber-300" /> {currentSlide === 2 ? "Reserve Table" : "Explore Menu"}
          </button>
          <button 
            className="inline-flex items-center justify-center px-6 py-3 text-sm font-semibold rounded-xl bg-[#f3ece2] text-stone-600 border border-stone-200 hover:bg-[#f3ece2] active:scale-95 transition-colors duration-200"
            onClick={() => setCurrentSlide((prev) => prev - 1)}
            onMouseEnter={handleHover}
            onMouseLeave={handleOut}
          >
            <MapPin className="w-4 h-4 mr-2" /> {currentSlide === 0 ? "View Location" : "Learn More"}
          </button>
        </div>

        {/* Decorative Glows */}
        <div className="absolute bottom-24 left-1/2 -translate-x-1/2 w-[400px] h-[400px] bg-[#f3ece2] rounded-full blur-3xl pointer-events-none" />
      </div>

      {/* Arrow Decorations */}
      <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-96 h-96 grid place-items-center pointer-events-none">
        <div className="w-1/2 h-1/2 bg-[#f3ece2] rounded-full blur-3xl pointer-events-none" />
        <Sparkle className="w-8 h-8 text-amber-600" />
      </div>
    </div>
  );
}

