                  className="block w-full bg-[#f3ece2] border border-stone-200 rounded-md py-2 pl-12 pr-4 text-sm focus:ring-2 focus:ring-amber-500 focus:ring-offset-2 placeholder:text-stone-500 sm:text-base"
