                    className="p-2 text-sm font-medium rounded-xl bg-[#f3ece2] border border-stone-200 hover:bg-[#f3ece2] hover:border-stone-200 transition-colors duration-200 cursor-pointer"
                    onClick={() => setFilterBy(label)}
