              <div className="h-6 w-2/3 bg-[#f3ece2] rounded" />
            </div>
          ) : (
            <>
              {filteredDishes.map((dish) => {
                const isFavorited = favoritedDishes.has(dish.id);
                const activeFilter = filterBy === 'All' || dish.name.startsWith(filterBy);
                if (!activeFilter) return null;
                return (
                  <div
                    key={dish.id}
                    className="group relative overflow-hidden rounded-2xl border border-stone-200 bg-[#f3ece2] p-6 transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] hover:border-stone-200 hover:bg-[#f3ece2]"
